"""Force repeated pinned local rendering and compare only canonical generated bytes."""
from pathlib import Path
import subprocess,json,hashlib,datetime,sys
R=Path(__file__).resolve().parent;P=R/'design-c4';E=P/'build/receipts';index=sys.argv[1] if len(sys.argv)>1 else '001';out=E/('reproducibility-'+index+'.json')
if out.exists():raise SystemExit('Immutable reproducibility receipt exists')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def hashes():
    paths=sorted((P/'docs').rglob('*.svg'))+[P/'docs/storyboards.html']
    return {str(p.relative_to(P)):sha(p) for p in paths}
args=json.loads((E/'gradle-package-015.request.json').read_text())['invocation'];args[-1]='./gradlew --offline --no-daemon -g .gradle-home --rerun-tasks verifyDesignDocs'
states=[hashes()];runs=[]
for n in (1,2):
    start=datetime.datetime.now(datetime.timezone.utc).isoformat();stdout=E/f'reproducibility-{index}-run{n}.stdout.txt';stderr=E/f'reproducibility-{index}-run{n}.stderr.txt'
    with stdout.open('x') as a,stderr.open('x') as b:r=subprocess.run(args,stdout=a,stderr=b)
    runs.append(dict(started_at=start,completed_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),exit_code=r.returncode,stdout_sha256=sha(stdout),stderr_sha256=sha(stderr)))
    states.append(hashes())
    if r.returncode:break
changed=[dict(file=k,hashes=[x.get(k) for x in states]) for k in sorted(set().union(*(x.keys() for x in states))) if len({x.get(k) for x in states})!=1]
result=dict(at=datetime.datetime.now(datetime.timezone.utc).isoformat(),invocation=args,runs=runs,generated_files=len(states[0]),all_render_hashes_identical=not changed and len(states)==3,changed=changed,hashes=states,scope='Pinned local SVG and self-contained Marp HTML bytes only; timestamped build receipts and resulting ZIP are inputs, not a claim of identical receipt timestamps across runs',no_source_or_model_edit=True)
out.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k not in ('hashes','invocation')}));raise SystemExit(0 if result['all_render_hashes_identical'] else 1)
